  output wire [1:0]    io_output_payload_ctx_GSharePlugin_GSHARE_COUNTER_0,
  output wire [1:0]    io_output_payload_ctx_GSharePlugin_GSHARE_COUNTER_1,
  output wire [1:0]    io_output_payload_ctx_GSharePlugin_GSHARE_COUNTER_2,
  output wire [1:0]    io_output_payload_ctx_GSharePlugin_GSHARE_COUNTER_3,
  output wire [1:0]    io_output_payload_ctx_GSharePlugin_GSHARE_COUNTER_4,
  output wire [1:0]    io_output_payload_ctx_GSharePlugin_GSHARE_COUNTER_5,
  output wire [1:0]    io_output_payload_ctx_GSharePlugin_GSHARE_COUNTER_6,
  output wire [1:0]    io_output_payload_ctx_GSharePlugin_GSHARE_COUNTER_7,
  output wire [0:0]    io_chosen,
  output wire [1:0]    io_chosenOH,
  input  wire          clk,
  input  wire          reset
);

  wire       [3:0]    _zz__zz_maskProposal_0_2;
  wire       [3:0]    _zz__zz_maskProposal_0_2_1;
  wire       [1:0]    _zz__zz_maskProposal_0_2_2;
  wire                locked;
  wire                maskProposal_0;
  wire                maskProposal_1;
  reg                 maskLocked_0;
  reg                 maskLocked_1;
  wire                maskRouted_0;
  wire                maskRouted_1;
  wire       [1:0]    _zz_maskProposal_0;
  wire       [3:0]    _zz_maskProposal_0_1;
  wire       [3:0]    _zz_maskProposal_0_2;
  wire       [1:0]    _zz_maskProposal_0_3;
  wire                _zz_io_chosen;

  assign _zz__zz_maskProposal_0_2 = (_zz_maskProposal_0_1 - _zz__zz_maskProposal_0_2_1);
  assign _zz__zz_maskProposal_0_2_2 = {maskLocked_0,maskLocked_1};
  assign _zz__zz_maskProposal_0_2_1 = {2'd0, _zz__zz_maskProposal_0_2_2};
  assign locked = 1'b0;
  assign maskRouted_0 = (locked ? maskLocked_0 : maskProposal_0);
  assign maskRouted_1 = (locked ? maskLocked_1 : maskProposal_1);
  assign _zz_maskProposal_0 = {io_inputs_1_valid,io_inputs_0_valid};
  assign _zz_maskProposal_0_1 = {_zz_maskProposal_0,_zz_maskProposal_0};
  assign _zz_maskProposal_0_2 = (_zz_maskProposal_0_1 & (~ _zz__zz_maskProposal_0_2));
  assign _zz_maskProposal_0_3 = (_zz_maskProposal_0_2[3 : 2] | _zz_maskProposal_0_2[1 : 0]);
  assign maskProposal_0 = _zz_maskProposal_0_3[0];
  assign maskProposal_1 = _zz_maskProposal_0_3[1];
  assign io_output_valid = ((io_inputs_0_valid && maskRouted_0) || (io_inputs_1_valid && maskRouted_1));
  assign io_output_payload_pcOnLastSlice = (maskRouted_0 ? io_inputs_0_payload_pcOnLastSlice : io_inputs_1_payload_pcOnLastSlice);
  assign io_output_payload_pcTarget = (maskRouted_0 ? io_inputs_0_payload_pcTarget : io_inputs_1_payload_pcTarget);
  assign io_output_payload_taken = (maskRouted_0 ? io_inputs_0_payload_taken : io_inputs_1_payload_taken);
  assign io_output_payload_isBranch = (maskRouted_0 ? io_inputs_0_payload_isBranch : io_inputs_1_payload_isBranch);
  assign io_output_payload_isPush = (maskRouted_0 ? io_inputs_0_payload_isPush : io_inputs_1_payload_isPush);
  assign io_output_payload_isPop = (maskRouted_0 ? io_inputs_0_payload_isPop : io_inputs_1_payload_isPop);
  assign io_output_payload_wasWrong = (maskRouted_0 ? io_inputs_0_payload_wasWrong : io_inputs_1_payload_wasWrong);
  assign io_output_payload_badPredictedTarget = (maskRouted_0 ? io_inputs_0_payload_badPredictedTarget : io_inputs_1_payload_badPredictedTarget);
  assign io_output_payload_history = (maskRouted_0 ? io_inputs_0_payload_history : io_inputs_1_payload_history);
  assign io_output_payload_uopId = (maskRouted_0 ? io_inputs_0_payload_uopId : io_inputs_1_payload_uopId);
  assign io_output_payload_ctx_GSharePlugin_GSHARE_COUNTER_0 = (maskRouted_0 ? io_inputs_0_payload_ctx_GSharePlugin_GSHARE_COUNTER_0 : io_inputs_1_payload_ctx_GSharePlugin_GSHARE_COUNTER_0);
  assign io_output_payload_ctx_GSharePlugin_GSHARE_COUNTER_1 = (maskRouted_0 ? io_inputs_0_payload_ctx_GSharePlugin_GSHARE_COUNTER_1 : io_inputs_1_payload_ctx_GSharePlugin_GSHARE_COUNTER_1);
  assign io_output_payload_ctx_GSharePlugin_GSHARE_COUNTER_2 = (maskRouted_0 ? io_inputs_0_payload_ctx_GSharePlugin_GSHARE_COUNTER_2 : io_inputs_1_payload_ctx_GSharePlugin_GSHARE_COUNTER_2);
  assign io_output_payload_ctx_GSharePlugin_GSHARE_COUNTER_3 = (maskRouted_0 ? io_inputs_0_payload_ctx_GSharePlugin_GSHARE_COUNTER_3 : io_inputs_1_payload_ctx_GSharePlugin_GSHARE_COUNTER_3);
  assign io_output_payload_ctx_GSharePlugin_GSHARE_COUNTER_4 = (maskRouted_0 ? io_inputs_0_payload_ctx_GSharePlugin_GSHARE_COUNTER_4 : io_inputs_1_payload_ctx_GSharePlugin_GSHARE_COUNTER_4);
  assign io_output_payload_ctx_GSharePlugin_GSHARE_COUNTER_5 = (maskRouted_0 ? io_inputs_0_payload_ctx_GSharePlugin_GSHARE_COUNTER_5 : io_inputs_1_payload_ctx_GSharePlugin_GSHARE_COUNTER_5);
  assign io_output_payload_ctx_GSharePlugin_GSHARE_COUNTER_6 = (maskRouted_0 ? io_inputs_0_payload_ctx_GSharePlugin_GSHARE_COUNTER_6 : io_inputs_1_payload_ctx_GSharePlugin_GSHARE_COUNTER_6);
  assign io_output_payload_ctx_GSharePlugin_GSHARE_COUNTER_7 = (maskRouted_0 ? io_inputs_0_payload_ctx_GSharePlugin_GSHARE_COUNTER_7 : io_inputs_1_payload_ctx_GSharePlugin_GSHARE_COUNTER_7);
  assign io_inputs_0_ready = (maskRouted_0 && io_output_ready);
  assign io_inputs_1_ready = (maskRouted_1 && io_output_ready);
  assign io_chosenOH = {maskRouted_1,maskRouted_0};
  assign _zz_io_chosen = io_chosenOH[1];
  assign io_chosen = _zz_io_chosen;
  always @(posedge clk or posedge reset) begin
    if(reset) begin
      maskLocked_0 <= 1'b0;
      maskLocked_1 <= 1'b1;
    end else begin
      if(io_output_valid) begin
        maskLocked_0 <= maskRouted_0;
        maskLocked_1 <= maskRouted_1;
      end
    end
  end


endmodule

module RamAsyncMwMux (
  input  wire          io_writes_0_valid,
  input  wire [4:0]    io_writes_0_payload_address,
  input  wire [63:0]   io_writes_0_payload_data,
  input  wire          io_writes_1_valid,
  input  wire [4:0]    io_writes_1_payload_address,
  input  wire [63:0]   io_writes_1_payload_data,
  input  wire          io_read_0_cmd_valid,
  input  wire [4:0]    io_read_0_cmd_payload,
  output wire [63:0]   io_read_0_rsp,
  input  wire          io_read_1_cmd_valid,
  input  wire [4:0]    io_read_1_cmd_payload,
  output wire [63:0]   io_read_1_rsp,
  input  wire          io_read_2_cmd_valid,
  input  wire [4:0]    io_read_2_cmd_payload,
  output wire [63:0]   io_read_2_rsp,
  input  wire          io_read_3_cmd_valid,
  input  wire [4:0]    io_read_3_cmd_payload,
  output wire [63:0]   io_read_3_rsp,
  input  wire          clk,
  input  wire          reset
);

  wire       [63:0]   ram_0_spinal_port1;
  wire       [63:0]   ram_0_spinal_port2;
  wire       [63:0]   ram_0_spinal_port3;
  wire       [63:0]   ram_0_spinal_port4;
  wire       [63:0]   ram_1_spinal_port1;
  wire       [63:0]   ram_1_spinal_port2;
  wire       [63:0]   ram_1_spinal_port3;
  wire       [63:0]   ram_1_spinal_port4;
  wire       [0:0]    location_io_read_0_rsp;
  wire       [0:0]    location_io_read_1_rsp;
  wire       [0:0]    location_io_read_2_rsp;
  wire       [0:0]    location_io_read_3_rsp;
  reg        [63:0]   _zz_io_read_0_rsp;
  reg        [63:0]   _zz_io_read_1_rsp;
  reg        [63:0]   _zz_io_read_2_rsp;
  reg        [63:0]   _zz_io_read_3_rsp;
  wire       [63:0]   reads_0_reads_0;
  wire       [63:0]   reads_0_reads_1;
  wire       [63:0]   reads_1_reads_0;
  wire       [63:0]   reads_1_reads_1;
  wire       [63:0]   reads_2_reads_0;
  wire       [63:0]   reads_2_reads_1;
  wire       [63:0]   reads_3_reads_0;
  wire       [63:0]   reads_3_reads_1;
  (* ram_style = "distributed" *) reg [63:0] ram_0 [0:31];
  (* ram_style = "distributed" *) reg [63:0] ram_1 [0:31];

  always @(posedge clk) begin
    if(io_writes_0_valid) begin
      ram_0[io_writes_0_payload_address] <= io_writes_0_payload_data;
    end
  end

  assign ram_0_spinal_port1 = ram_0[io_read_0_cmd_payload];
  assign ram_0_spinal_port2 = ram_0[io_read_1_cmd_payload];
  assign ram_0_spinal_port3 = ram_0[io_read_2_cmd_payload];
  assign ram_0_spinal_port4 = ram_0[io_read_3_cmd_payload];
  always @(posedge clk) begin
    if(io_writes_1_valid) begin
      ram_1[io_writes_1_payload_address] <= io_writes_1_payload_data;
    end
  end

  assign ram_1_spinal_port1 = ram_1[io_read_0_cmd_payload];
  assign ram_1_spinal_port2 = ram_1[io_read_1_cmd_payload];
  assign ram_1_spinal_port3 = ram_1[io_read_2_cmd_payload];
  assign ram_1_spinal_port4 = ram_1[io_read_3_cmd_payload];
  RamAsyncMwXor location (
    .io_writes_0_valid           (io_writes_0_valid               ), //i
    .io_writes_0_payload_address (io_writes_0_payload_address[4:0]), //i
    .io_writes_0_payload_data    (1'b0                            ), //i
    .io_writes_1_valid           (io_writes_1_valid               ), //i
    .io_writes_1_payload_address (io_writes_1_payload_address[4:0]), //i
    .io_writes_1_payload_data    (1'b1                            ), //i
    .io_read_0_cmd_valid         (io_read_0_cmd_valid             ), //i
    .io_read_0_cmd_payload       (io_read_0_cmd_payload[4:0]      ), //i
    .io_read_0_rsp               (location_io_read_0_rsp          ), //o
    .io_read_1_cmd_valid         (io_read_1_cmd_valid             ), //i
    .io_read_1_cmd_payload       (io_read_1_cmd_payload[4:0]      ), //i
    .io_read_1_rsp               (location_io_read_1_rsp          ), //o
    .io_read_2_cmd_valid         (io_read_2_cmd_valid             ), //i
    .io_read_2_cmd_payload       (io_read_2_cmd_payload[4:0]      ), //i
    .io_read_2_rsp               (location_io_read_2_rsp          ), //o
    .io_read_3_cmd_valid         (io_read_3_cmd_valid             ), //i
    .io_read_3_cmd_payload       (io_read_3_cmd_payload[4:0]      ), //i
    .io_read_3_rsp               (location_io_read_3_rsp          ), //o
    .clk                         (clk                             ), //i
    .reset                       (reset                           )  //i
  );
  always @(*) begin
    case(location_io_read_0_rsp)
      1'b0 : _zz_io_read_0_rsp = reads_0_reads_0;
      default : _zz_io_read_0_rsp = reads_0_reads_1;
    endcase
  end

  always @(*) begin
    case(location_io_read_1_rsp)
      1'b0 : _zz_io_read_1_rsp = reads_1_reads_0;
      default : _zz_io_read_1_rsp = reads_1_reads_1;
    endcase
  end

  always @(*) begin
    case(location_io_read_2_rsp)
      1'b0 : _zz_io_read_2_rsp = reads_2_reads_0;
      default : _zz_io_read_2_rsp = reads_2_reads_1;
    endcase
  end

  always @(*) begin
    case(location_io_read_3_rsp)
      1'b0 : _zz_io_read_3_rsp = reads_3_reads_0;
      default : _zz_io_read_3_rsp = reads_3_reads_1;
    endcase
  end

  assign reads_0_reads_0 = ram_0_spinal_port1;
  assign reads_0_reads_1 = ram_1_spinal_port1;
  assign io_read_0_rsp = _zz_io_read_0_rsp;
  assign reads_1_reads_0 = ram_0_spinal_port2;
  assign reads_1_reads_1 = ram_1_spinal_port2;
  assign io_read_1_rsp = _zz_io_read_1_rsp;
  assign reads_2_reads_0 = ram_0_spinal_port3;
  assign reads_2_reads_1 = ram_1_spinal_port3;
  assign io_read_2_rsp = _zz_io_read_2_rsp;
  assign reads_3_reads_0 = ram_0_spinal_port4;
  assign reads_3_reads_1 = ram_1_spinal_port4;
  assign io_read_3_rsp = _zz_io_read_3_rsp;

endmodule

module RamAsyncMwXor (
  input  wire          io_writes_0_valid,
  input  wire [4:0]    io_writes_0_payload_address,
  input  wire [0:0]    io_writes_0_payload_data,
  input  wire          io_writes_1_valid,
  input  wire [4:0]    io_writes_1_payload_address,
  input  wire [0:0]    io_writes_1_payload_data,
  input  wire          io_read_0_cmd_valid,
  input  wire [4:0]    io_read_0_cmd_payload,
  output wire [0:0]    io_read_0_rsp,
  input  wire          io_read_1_cmd_valid,
  input  wire [4:0]    io_read_1_cmd_payload,
  output wire [0:0]    io_read_1_rsp,
  input  wire          io_read_2_cmd_valid,
  input  wire [4:0]    io_read_2_cmd_payload,
  output wire [0:0]    io_read_2_rsp,
  input  wire          io_read_3_cmd_valid,
  input  wire [4:0]    io_read_3_cmd_payload,
  output wire [0:0]    io_read_3_rsp,
  input  wire          clk,
  input  wire          reset
);

  wire       [0:0]    ram_0_spinal_port1;
  wire       [0:0]    ram_0_spinal_port2;
  wire       [0:0]    ram_0_spinal_port3;
  wire       [0:0]    ram_0_spinal_port4;
  wire       [0:0]    ram_0_spinal_port5;
  wire       [0:0]    ram_1_spinal_port0;
  wire       [0:0]    ram_1_spinal_port2;
  wire       [0:0]    ram_1_spinal_port3;
  wire       [0:0]    ram_1_spinal_port4;
  wire       [0:0]    ram_1_spinal_port5;
  wire       [0:0]    writes_0_values_0;
  wire       [0:0]    writes_0_xored;
  wire       [0:0]    writes_1_values_0;
  wire       [0:0]    writes_1_xored;
  wire       [0:0]    reads_0_values_0;
  wire       [0:0]    reads_0_values_1;
  wire       [0:0]    reads_0_xored;
  wire       [0:0]    reads_1_values_0;
  wire       [0:0]    reads_1_values_1;
  wire       [0:0]    reads_1_xored;
  wire       [0:0]    reads_2_values_0;
  wire       [0:0]    reads_2_values_1;
  wire       [0:0]    reads_2_xored;
  wire       [0:0]    reads_3_values_0;
  wire       [0:0]    reads_3_values_1;
  wire       [0:0]    reads_3_xored;
  (* ram_style = "distributed" *) reg [0:0] ram_0 [0:31];
  (* ram_style = "distributed" *) reg [0:0] ram_1 [0:31];

integer verilogIndex;

initial begin
  for (verilogIndex = 0; verilogIndex < 32; verilogIndex = verilogIndex + 1)begin
ram_0[verilogIndex] = -1;
  end
end
  always @(posedge clk) begin
    if(io_writes_0_valid) begin
      ram_0[io_writes_0_payload_address] <= writes_0_xored;
    end
  end

  assign ram_0_spinal_port1 = ram_0[io_writes_1_payload_address];
  assign ram_0_spinal_port2 = ram_0[io_read_0_cmd_payload];
  assign ram_0_spinal_port3 = ram_0[io_read_1_cmd_payload];
  assign ram_0_spinal_port4 = ram_0[io_read_2_cmd_payload];
  assign ram_0_spinal_port5 = ram_0[io_read_3_cmd_payload];

initial begin
  for (verilogIndex = 0; verilogIndex < 32; verilogIndex = verilogIndex + 1)begin
ram_1[verilogIndex] = -1;
  end
end
  assign ram_1_spinal_port0 = ram_1[io_writes_0_payload_address];
  always @(posedge clk) begin
    if(io_writes_1_valid) begin
      ram_1[io_writes_1_payload_address] <= writes_1_xored;
    end
  end

  assign ram_1_spinal_port2 = ram_1[io_read_0_cmd_payload];
  assign ram_1_spinal_port3 = ram_1[io_read_1_cmd_payload];
  assign ram_1_spinal_port4 = ram_1[io_read_2_cmd_payload];
  assign ram_1_spinal_port5 = ram_1[io_read_3_cmd_payload];
  assign writes_0_values_0 = ram_1_spinal_port0;
  assign writes_0_xored = (io_writes_0_payload_data ^ writes_0_values_0);
  assign writes_1_values_0 = ram_0_spinal_port1;
  assign writes_1_xored = (io_writes_1_payload_data ^ writes_1_values_0);
  assign reads_0_values_0 = ram_0_spinal_port2;
  assign reads_0_values_1 = ram_1_spinal_port2;
  assign reads_0_xored = (reads_0_values_0 ^ reads_0_values_1);
  assign io_read_0_rsp = reads_0_xored;
  assign reads_1_values_0 = ram_0_spinal_port3;
  assign reads_1_values_1 = ram_1_spinal_port3;
  assign reads_1_xored = (reads_1_values_0 ^ reads_1_values_1);
  assign io_read_1_rsp = reads_1_xored;
  assign reads_2_values_0 = ram_0_spinal_port4;
  assign reads_2_values_1 = ram_1_spinal_port4;
  assign reads_2_xored = (reads_2_values_0 ^ reads_2_values_1);
  assign io_read_2_rsp = reads_2_xored;
  assign reads_3_values_0 = ram_0_spinal_port5;
  assign reads_3_values_1 = ram_1_spinal_port5;
  assign reads_3_xored = (reads_3_values_0 ^ reads_3_values_1);
  assign io_read_3_rsp = reads_3_xored;

endmodule
